input.sparql:
SELECT ?point ?series WHERE {
  ?z rdfs:label "Perimeter_top_ZN_1" .
  ?p brick:isPointOf ?z ;
     a brick:Occupancy ;
     ref:hasTimeseriesId ?series .
}

SELECT ?point ?series ?cls WHERE {
  <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z02> 
  ?p a ?cls ;
     brick:isPointOf <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z02> ;
     ref:hasTimeseriesId ?series .
  BIND(STR(?p) AS ?point)
}

SELECT ?p ?cls ?series WHERE {
  ?p brick:isPointOf <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z02> .
  OPTIONAL { ?p a ?cls . }
  OPTIONAL { ?p ref:hasTimeseriesId ?series . }
}

SELECT ?p ?x WHERE {
  ?p brick:isPointOf <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z02> ;
     a brick:Occupancy_Sensor .
  ?p ?x ?y .
  FILTER(?x != brick:isPointOf && ?x != rdf:type)
}
